// Minimal producer (ISR) enqueue
int enq(struct ring *r, struct evt *e){
  int idx = atomic_load_explicit(&r->head, memory_order_relaxed) & (RING_MASK);
  if (atomic_load_explicit(&r->slots[idx].claimed, memory_order_acquire))
    return -1;
  r->slots[idx].evt = *e;
  atomic_store_explicit(&r->slots[idx].claimed, 1, memory_order_release);
  atomic_fetch_add_explicit(&r->head, 1, memory_order_release);
  return 0;
}
