typedef struct { int tokens; int capacity; } bucket;
bucket buckets[MAX_PROCS];

int io_request(int pid, int bytes){
  if (buckets[pid].tokens >= bytes){
    buckets[pid].tokens -= bytes;
    submit_disk(pid, bytes);
    return 1;
